    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def bst_contains(root, value):
    cur = root
    while cur:
        if value == cur.value:
            return True
        cur = cur.left if value < cur.value else cur.right
    return False

