class TreeNode:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def is_bst(root):
    def helper(node, lo, hi):
        if node is None:
            return True
        if not (lo < node.value < hi):
            return False
        return helper(node.left, lo, node.value) and helper(node.right, node.value, hi)
    return helper(root, float('-inf'), float('inf'))
